def separate_paren_groups(s):
    res = []
    current_group = []
    open_paren_count = 0
    for char in s:
        if char == '(':
            open_paren_count += 1
            current_group.append(char)
        elif char == ')':
            open_paren_count -= 1
            current_group.append(char)
            if open_paren_count == 0:
                res.append(''.join(current_group))
                current_group = []
        else:
            current_group.append(char)
    return res
```
